using Microsoft.AspNetCore.Http;

namespace BlazorFrame.AspNetCore;

/// <summary>
/// Applies policies generated by BlazorFrame to an HTTP response before it starts.
/// </summary>
public static class CspResponseExtensions
{
    /// <summary>
    /// Generates and applies a CSP header. Call this from middleware, an endpoint, or
    /// a host page before the response headers are sent.
    /// </summary>
    public static CspHeader ApplyBlazorFrameCsp(
        this HttpResponse response,
        CspOptions options,
        IEnumerable<string>? iframeSources = null,
        bool overwrite = false)
    {
        ArgumentNullException.ThrowIfNull(response);
        ArgumentNullException.ThrowIfNull(options);

        var header = new Services.CspBuilderService().BuildCspHeader(options, iframeSources);
        if (overwrite || !response.Headers.ContainsKey(header.HeaderName))
            response.Headers[header.HeaderName] = header.HeaderValue;

        return header;
    }
}
